import{t as e}from"./LegalDocument-DvFXSN17.js";import{y as t}from"./icons-CwyibDqE.js";var n={pt:{intro:`As regras para usares o Kayé: o que podes esperar de nós, o que esperamos de ti e o que acontece quando algo corre mal.`,summary:[`Explorar o Kayé é grátis. Nos Kursos, a conta grátis faz um tópico por dia; o Kayé Plus (pago, para maiores de 18 anos) tira o limite e inclui o certificado e os lembretes. Durante o teste de Natal, o Plus é grátis para todos, e avisamos antes de passar a pago.`,`O Kayé orienta, não decide por ti nem garante emprego, bolsa ou vaga num curso. A decisão é sempre tua.`,`Nada que seja pago influencia as recomendações.`,`A informação vem de fontes que indicamos, mas pode mudar ou ter erros: confirma com a instituição antes de pagar ou de te inscreveres.`,`O teu CV e o que escreves são teus. Podes apagar a tua conta e os teus dados quando quiseres.`,`Entre os 14 e os 17 anos podes usar o Kayé com o conhecimento do teu encarregado de educação.`,`Estes termos regem-se pela lei angolana. Os teus direitos de consumidor ficam sempre protegidos.`],sections:[{id:`quem-somos`,title:`Quem somos e o que estes termos são`,body:[`O Kayé é uma plataforma de orientação de carreira para jovens em Angola, disponível no site kayeangola.com e nas aplicações que o Kayé publicar (o «Serviço»). Neste texto, «Kayé», «nós» e «nosso» designam a entidade que opera o Serviço{operator}. «Tu» és a pessoa que usa o Serviço.`,`Estes termos são o contrato entre ti e o Kayé. Fazem parte dele a Política de privacidade, que explica como tratamos os teus dados, e os avisos específicos que aparecerem junto de uma funcionalidade (por exemplo, as regras das entrevistas ou do Kayé Plus). Se houver diferença entre eles, o aviso específico prevalece sobre estes termos para essa funcionalidade.`,`Ao criar um perfil, ao entrar com a tua conta Google ou ao continuar a usar o Serviço depois de os leres, aceitas estes termos. Se não concordas, não uses o Serviço: podes continuar a explorar o que está aberto sem criar perfil, mas sem guardar nada.`]},{id:`o-que-e`,title:`O que é o Kayé`,body:[`O Kayé ajuda jovens dos 14 aos 30 anos a descobrir profissões, o que cada uma exige, quanto paga e procura tem, onde estudar e como se preparar: testes vocacionais, comparação de cursos, instituições e empresas, prazos de bolsas e candidaturas, treino para exames e entrevistas, e um criador de CV.`,`O Kayé é um serviço de orientação e de informação. Não é um site de emprego, não recruta pessoas, não é uma instituição de ensino, não concede bolsas, não faz aconselhamento psicológico, jurídico, médico ou financeiro, e não representa nenhuma instituição ou empresa.`]},{id:`quem-pode-usar`,title:`Quem pode usar`,body:[`Qualquer pessoa pode explorar o que está aberto sem criar perfil. Para criares um perfil tens de ter pelo menos 14 anos, dar informação verdadeira e aceitar estes termos e a Política de privacidade.`,`Se tens entre 14 e 17 anos, só podes usar o Kayé com o conhecimento e a autorização do teu encarregado de educação, que declaras ao criar o perfil. Ele pode pedir-nos a qualquer momento para apagar a tua conta. Se és encarregado de educação e não concordas que um menor use o Kayé, escreve-nos e apagamos a conta.`,`Por segurança, os perfis de menores nunca são públicos, não veem salários, não recebem mensagens de promoção e não podem subscrever funcionalidades pagas.`,`Tens de nos dar informação verdadeira e manter o teu perfil atualizado. Podemos pedir-te que confirmes a tua idade e, se for caso disso, a autorização do teu encarregado de educação.`]},{id:`conta`,title:`A tua conta`,body:[`Entras no Kayé com a tua conta Google. Não vemos a tua palavra-passe do Google. És responsável por tudo o que acontece na tua conta e por proteger o acesso ao teu email e ao teu aparelho.`,`A conta é pessoal: não a partilhes nem a cedas. Se achares que alguém entrou na tua conta sem autorização, avisa-nos de imediato em {email}.`,`Podes apagar a tua conta e os teus dados quando quiseres, em Configurações. Apagar é definitivo e não podemos recuperar o que apagaste.`]},{id:`gratis-plus`,title:`Grátis, Kayé Plus e pagamentos`,body:[`Explorar o Kayé é grátis: descobrir carreiras, áreas, cursos, instituições, empresas, o mercado, as notícias, os prazos, as bolsas e os estágios, fazer o teu primeiro teste vocacional, acompanhar a tua sequência e responder ao desafio do dia. O que hoje é grátis para exploração não passa a ser pago sem aviso prévio.`,`O que é personalizado faz parte do Kayé Plus, uma subscrição paga para maiores de 18 anos: os Kursos sem limite diário e com exame final, o certificado dos Kursos, os lembretes e as subscrições (avisos de prazos por email e por notificações), o plano pessoal («O meu plano»), o CV em PDF, o treino psicotécnico e dos exames de acesso sem limite, as simulações sem limite e as entrevistas com feedback da equipa. O CV em PDF, o treino, as simulações e as entrevistas podem ser experimentados uma vez, de graça.`,`Nos Kursos, a conta grátis faz um tópico por dia: o dia conta quando concluis o tópico, e os outros ficam com cadeado até ao dia seguinte. A conta grátis não recebe o certificado dos Kursos. O certificado é um reconhecimento do Kayé: não é um diploma oficial, não substitui um curso reconhecido e não garante emprego, bolsa ou vaga.`,`Se tens menos de 18 anos, fazes um tópico por dia nos Kursos, sem certificado, e não vês promoções do Kayé Plus. Nunca te cobramos nada.`,`Presente de Natal: durante o período de teste, o Kayé Plus é grátis para todos e não cobramos nada. Avisamos-te na app e/ou por email com pelo menos 30 dias de antecedência antes de o Plus passar a ser pago, e só cobramos depois de aceitares as condições.`,`O preço previsto do Kayé Plus é de 1.999 kwanzas por mês e pode mudar antes de abrir. Antes de pagares, mostramos-te, em kwanzas e com impostos incluídos, o preço, o período, as funcionalidades incluídas, o meio de pagamento e como cancelar.`,[`Se a subscrição se renovar automaticamente, avisamos-te antes de cada renovação e podes cancelar a qualquer momento nas Configurações; o cancelamento produz efeitos no fim do período já pago.`,`Podemos alterar o preço do Kayé Plus. A alteração só vale para os períodos seguintes e avisamos-te com pelo menos 30 dias de antecedência, para decidires se continuas.`,`Sem prejuízo dos direitos que a lei de defesa do consumidor te dá, não reembolsamos o período que já começou, salvo se o Serviço falhar por culpa nossa durante uma parte relevante desse período.`,`Os pagamentos são processados por prestadores de serviços de pagamento autorizados. O Kayé não guarda os dados do teu cartão ou da tua conta de pagamento.`]]},{id:`independencia`,title:`Independência das recomendações`,body:[`Nenhuma instituição ou empresa paga para aparecer primeiro. Nada que seja pago, incluindo o Kayé Plus, influencia as recomendações, a ordem do que vês, a classificação dos cursos ou o teu encaixe com uma profissão.`,`Os critérios da classificação dos cursos são públicos e estão explicados na própria app. Se algum dia houver conteúdo patrocinado, será sempre identificado como tal e separado do resto.`]},{id:`informacao`,title:`A informação que mostramos`,body:[`Reunimos a informação de fontes públicas e oficiais e indicamos a fonte sempre que possível. Mesmo assim, as profissões, os salários, os preços das propinas, os prazos e as vagas mudam, e podemos errar ou estar desatualizados.`,`Alguns números e textos são estimativas ou exemplos, e dizemos quando é o caso («Estimado», «Exemplo»). As instituições marcadas como «Exemplo» não são reais. As instituições reais só mostram factos de fontes públicas ou que nos confirmaram.`,`O teste vocacional, o encaixe com cada profissão, as recomendações e os desafios dão pistas sobre os teus interesses e o mercado. Não são um diagnóstico, uma avaliação psicológica, uma prova de aptidão nem um parecer profissional.`,`Antes de uma decisão importante, como pagar uma inscrição, mudar de curso ou recusar uma oferta, confirma diretamente com a instituição, a empresa ou a entidade oficial. Se vires um erro, diz-nos em {email} e corrigimos.`]},{id:`sem-garantias`,title:`Orientação, não promessas`,body:[`O Kayé não garante que encontres emprego, que sejas admitido numa instituição, que consigas uma bolsa ou um estágio, que ganhes um certo salário ou que uma carreira tenha procura no futuro. Os resultados dependem de ti e de muitas coisas que não controlamos.`,`As decisões que tomas sobre os teus estudos, o teu trabalho e o teu dinheiro são tuas e da tua responsabilidade.`]},{id:`regras`,title:`Regras de utilização`,body:[`Usa o Kayé de forma honesta, legal e com respeito pelos outros. Não é permitido:`,[`dar informação falsa de propósito, por exemplo num testemunho, num salário, no teu perfil ou num pedido a um mentor;`,`fazer-te passar por outra pessoa ou por uma instituição ou empresa;`,`publicar ou pedir dados pessoais de outras pessoas sem autorização;`,`insultar, ameaçar, assediar ou discriminar alguém, ou publicar conteúdo ilegal, ofensivo, violento ou sexualmente explícito;`,`tentar entrar em partes do Serviço a que não tens acesso, contornar medidas de segurança, testar vulnerabilidades sem a nossa autorização escrita ou perturbar o funcionamento do Serviço;`,`copiar, recolher ou reutilizar os conteúdos, os dados ou a classificação do Kayé de forma automática ou em massa (robôs, extração de dados, scraping), ou revendê-los;`,`usar o Serviço para enviar mensagens não solicitadas ou publicidade;`,`usar o Kayé para fins contrários à lei, em especial à Lei de Proteção das Redes e Sistemas Informáticos.`],`Quando existirem testemunhos e outras contribuições, são revistos antes de aparecerem. Podemos recusar, editar ou retirar o que não cumpra estas regras, e comunicar às autoridades o que a lei nos obrigue a comunicar.`]},{id:`o-teu-conteudo`,title:`O teu conteúdo`,body:[`O teu CV, as tuas respostas e tudo o que escreves no Kayé continuam a ser teus. Não ficamos com a propriedade de nada disto.`,`Para o Serviço funcionar, dás ao Kayé uma licença gratuita, não exclusiva e limitada para guardar, processar e mostrar esse conteúdo apenas a ti e às pessoas que escolheres (por exemplo, quando publicas o teu cartão de visita), e para o tratar como a Política de privacidade explica. A licença acaba quando apagas o conteúdo ou a conta, salvo cópias de segurança que se apagam no ciclo normal.`,`Se publicares o teu cartão de visita, tu decides o que aparece e podes desligá-lo quando quiseres. És responsável pelo que escreves e garantes que tens o direito de o publicar.`,`Se nos enviares sugestões, críticas ou ideias, podemos usá-las sem te pagar nem te dar crédito, mas sem tornar públicos os teus dados pessoais.`,`Os CVs modelo são de pessoas fictícias. Podes usá-los à vontade como ponto de partida para o teu.`]},{id:`propriedade`,title:`Propriedade intelectual do Kayé`,body:[`O nome, o logótipo, o desenho, o software, a base de dados, a classificação, os textos e os restantes conteúdos do Kayé pertencem ao Kayé ou a quem nos licenciou, e estão protegidos pela lei angolana sobre direitos de autor e propriedade industrial.`,`Estes termos não te dão nenhum direito sobre isto além do que dizem: damos-te apenas o direito pessoal, limitado, revogável e não transmissível de usar o Serviço para a tua orientação pessoal. Não podes copiar, modificar, distribuir, vender, alugar ou fazer engenharia inversa do Serviço, nem usar a marca Kayé sem a nossa autorização escrita.`,`Os nomes e os logótipos das instituições e das empresas pertencem aos seus donos e aparecem só para as identificar. As fotos pertencem aos seus autores e são usadas segundo as respetivas licenças. Se és titular de um direito e achas que algo viola esse direito, escreve para {email} com a indicação do conteúdo e do direito, e analisamos e, se for caso disso, retiramos.`]},{id:`terceiros`,title:`Instituições, empresas e ligações de terceiros`,body:[`O Kayé mostra instituições, empresas, bolsas, estágios e notícias que não são nossas. Não somos parte da relação entre ti e elas, não as representamos nem as recomendamos por si só, e não respondemos pelo que fazem, prometem ou deixam de fazer.`,`As ligações para sites de terceiros são uma comodidade. Não controlamos esses sites, não os endossamos e usá-los é por tua conta e risco, segundo os termos deles.`,`Quando uma instituição ou empresa publicar algo no Kayé, é ela a responsável pelo que publica. Nunca lhes damos os teus dados individuais.`]},{id:`funcionalidades`,title:`Entrevistas, mentores e outras funcionalidades com pessoas`,body:[`Treino de entrevistas com feedback: as respostas que decides enviar são lidas pela equipa do Kayé para te darmos feedback e são tratadas como a Política de privacidade explica. O feedback é uma opinião para te ajudar a treinar, não uma avaliação oficial nem uma promessa de resultado.`,`Mentores: os mentores são pessoas independentes aprovadas por nós. Não são funcionários nem agentes do Kayé, e as conversas combinadas contigo são entre ti e eles. O Kayé não garante o conteúdo dessas conversas. Não partilhes dados sensíveis nem pagamentos fora das regras do Serviço.`,`CV em PDF e cartão de visita: o documento é criado no teu aparelho com o que escreveste. Verifica-o antes de o enviares: és responsável pelo seu conteúdo.`]},{id:`avisos`,title:`Comunicações e avisos`,body:[`Enviamos-te mensagens do Serviço quando são necessárias (por exemplo, a confirmação do teu email, lembretes de prazos que guardaste, mudanças a estes termos ou avisos de segurança).`,`Só te enviamos novidades e promoções se nos deres consentimento para esse canal (email ou notificações), que podes retirar a qualquer momento nas Configurações ou no link que vem em cada email. Nunca enviamos promoções a menores de 18 anos.`,`Respeitamos a lei sobre comunicações eletrónicas não solicitadas. Fazemos o envio de WhatsApp só à mão e só a quem o pediu.`]},{id:`privacidade`,title:`Os teus dados pessoais`,body:[`Tratamos os teus dados pessoais de acordo com a Lei n.º 22/11, de 17 de junho, da Proteção de Dados Pessoais, e conforme explicado na nossa Política de privacidade, que faz parte destes termos. Aí dizemos que dados recolhemos, para quê, durante quanto tempo, com quem os partilhamos e como exerces os teus direitos.`]},{id:`disponibilidade`,title:`Disponibilidade do serviço`,body:[`Fazemos o possível para que o Kayé esteja sempre disponível, mas não garantimos que funcione sem interrupções nem sem erros. Podemos parar o Serviço, ou parte dele, para manutenção, atualizações, motivos de segurança ou por problemas fora do nosso controlo (falhas de energia, de internet, de fornecedores).`,`Podemos mudar, acrescentar ou retirar funcionalidades. Quando uma mudança te afetar de forma relevante, avisamos com antecedência razoável.`,`O Kayé foi pensado para telemóveis com ligação lenta. Se tiveres pouca internet, algumas partes podem demorar ou não abrir.`]},{id:`responsabilidade`,title:`Limites da nossa responsabilidade`,body:[`O Serviço é prestado «tal como está» e «conforme disponível». Na medida máxima que a lei permite, o Kayé não responde por: decisões que tomes com base na informação do Serviço; erros, atrasos ou omissões nos dados publicados pelas instituições, empresas e outras fontes; indisponibilidade do Serviço; perda de lucros, de oportunidades, de dados ou outros danos indiretos ou consequentes; nem por atos de terceiros, incluindo instituições, empresas, mentores e outros utilizadores.`,`Se, apesar disto, formos responsáveis perante ti, a nossa responsabilidade total limita-se, na medida em que a lei o permita, ao valor que tiveres pago ao Kayé nos 12 meses anteriores ao facto que deu origem à reclamação (ou, se o Serviço foi gratuito para ti, ao mínimo que a lei permitir).`,`Nada nestes termos exclui ou limita a responsabilidade que a lei não permite excluir ou limitar, como a responsabilidade por dolo, por culpa grave, por danos à vida, à integridade física ou à saúde, ou os direitos que a lei de defesa do consumidor te garante e que não podem ser afastados por contrato.`]},{id:`indemnizacao`,title:`Responsabilidade pelo teu uso`,body:[`És responsável pelo uso que fazes do Serviço e pelo que publicas nele. Se violares estes termos ou a lei, e isso causar danos ao Kayé ou a terceiros (por exemplo, publicares conteúdo ilícito ou que viole direitos de outros), podes ter de nos compensar pelos prejuízos e custos razoáveis daí resultantes, na medida em que a lei o permita.`]},{id:`suspensao`,title:`Suspender, encerrar e sair`,body:[`Podes deixar de usar o Kayé e apagar a tua conta quando quiseres.`,`Podemos suspender ou encerrar o acesso de quem viole estes termos ou a lei, ponha em risco a segurança do Serviço ou de outras pessoas, ou use o Serviço de forma fraudulenta. Sempre que possível, avisamos primeiro e explicamos o motivo, e podes responder-nos em {email}. Em casos graves ou urgentes podemos suspender de imediato.`,`Se uma conta paga for encerrada por nossa decisão sem que tenhas violado estes termos, devolvemos o valor proporcional ao período pago e não usado.`,`O que, pela sua natureza, deve continuar depois do fim do contrato (propriedade intelectual, limites de responsabilidade, lei aplicável e resolução de litígios) continua.`]},{id:`forca-maior`,title:`Casos de força maior`,body:[`Nenhuma das partes responde por falhas no cumprimento causadas por acontecimentos fora do seu controlo razoável, como catástrofes naturais, guerra, atos das autoridades, falhas gerais de energia ou de telecomunicações, ataques informáticos apesar das medidas razoáveis de segurança, ou falhas de fornecedores essenciais. A parte afetada avisa a outra e retoma o cumprimento assim que possível.`]},{id:`alteracoes`,title:`Alterações a estes termos`,body:[`Podemos atualizar estes termos para refletir mudanças no Serviço, na lei ou na forma como trabalhamos. A data da versão em vigor está no topo desta página.`,`Se a mudança for importante, avisamos-te na app e/ou por email com pelo menos 30 dias de antecedência (ou logo que possível, se for exigida por lei ou por segurança) e pedimos-te que aceites a nova versão. Se não concordares, podes apagar a tua conta antes de a mudança entrar em vigor. Continuar a usar o Serviço depois dessa data significa que aceitas a nova versão.`]},{id:`disposicoes`,title:`Disposições gerais`,body:[`Estes termos, com a Política de privacidade e os avisos específicos, são o acordo completo entre ti e o Kayé sobre o Serviço e substituem entendimentos anteriores.`,`Se uma parte destes termos for inválida ou não puder ser aplicada, as outras partes continuam em vigor e a parte inválida é substituída pela que mais se aproxime do seu objetivo. Não exercer um direito não significa renunciar a ele.`,`Não podes ceder os teus direitos e obrigações a outra pessoa. O Kayé pode transmitir o Serviço e este contrato a outra entidade, por exemplo numa reorganização, avisando-te e sem diminuir os teus direitos.`,`Aceitas receber as comunicações sobre o Serviço por meios eletrónicos (a app e o email que deste). O Kayé pode ser lido em português, inglês e francês: em caso de dúvida ou diferença, vale o texto em português.`]},{id:`lei-litigios`,title:`Lei aplicável, reclamações e litígios`,body:[`Estes termos regem-se pela lei da República de Angola.`,`Se tiveres uma queixa, escreve-nos primeiro em {email}: respondemos em prazo razoável e tentamos resolver amigavelmente. Se és consumidor, podes também recorrer às entidades de defesa do consumidor, como o Instituto Nacional de Defesa do Consumidor (INADEC), e, quanto a dados pessoais, à Agência de Proteção de Dados (APD).`,`Para os litígios que não se resolvam amigavelmente, são competentes os tribunais da comarca de Luanda, sem prejuízo das regras imperativas que te permitam recorrer aos tribunais do teu domicílio e dos meios de resolução alternativa de litígios a que a lei te dá direito. Nada aqui te obriga a recorrer à arbitragem.`]},{id:`contacto`,title:`Contacto`,body:[`Dúvidas, pedidos ou reclamações sobre estes termos: {email}.`]}]},en:{intro:`The rules for using Kayé: what you can expect from us, what we expect from you and what happens when something goes wrong.`,summary:[`Exploring Kayé is free. In the Kursos, a free account does one topic a day; Kayé Plus (paid, for people over 18) removes the limit and includes the certificate and the reminders. During the Christmas trial, Plus is free for everyone, and we warn you before it becomes paid.`,`Kayé guides, it does not decide for you, and it does not guarantee a job, a scholarship or a place on a course. The decision is always yours.`,`Nothing paid influences the recommendations.`,`The information comes from sources we name, but it can change or contain errors: check with the institution before you pay or enrol.`,`Your CV and what you write are yours. You can delete your account and your data whenever you want.`,`Between 14 and 17 you can use Kayé with your guardian’s knowledge.`,`These terms are governed by Angolan law. Your consumer rights are always protected.`],sections:[{id:`quem-somos`,title:`Who we are and what these terms are`,body:[`Kayé is a career guidance platform for young people in Angola, available on kayeangola.com and in the apps Kayé publishes (the “Service”). In this text, “Kayé”, “we” and “our” mean the entity that operates the Service{operator}. “You” is the person who uses the Service.`,`These terms are the contract between you and Kayé. The Privacy Policy, which explains how we handle your data, and the specific notices shown next to a feature (for example, the rules of the interviews or of Kayé Plus) are part of it. If they differ, the specific notice prevails over these terms for that feature.`,`By creating a profile, signing in with your Google account or continuing to use the Service after reading them, you accept these terms. If you do not agree, do not use the Service: you can keep exploring what is open without creating a profile, but you cannot save anything.`]},{id:`o-que-e`,title:`What Kayé is`,body:[`Kayé helps people aged 14 to 30 discover careers, what each one requires, what it pays and how much demand it has, where to study and how to prepare: vocational tests, a comparison of courses, institutions and companies, deadlines for scholarships and applications, practice for exams and interviews, and a CV builder.`,`Kayé is a guidance and information service. It is not a job site, it does not recruit people, it is not an educational institution, it does not award scholarships, it does not give psychological, legal, medical or financial advice, and it does not represent any institution or company.`]},{id:`quem-pode-usar`,title:`Who can use it`,body:[`Anyone can explore what is open without creating a profile. To create a profile you must be at least 14, give truthful information and accept these terms and the Privacy Policy.`,`If you are between 14 and 17, you may only use Kayé with the knowledge and permission of your guardian, which you declare when creating the profile. They can ask us at any time to delete your account. If you are a guardian and you do not agree that a minor uses Kayé, write to us and we will delete the account.`,`For safety, minors’ profiles are never public, they do not see salaries, they receive no promotional messages and they cannot subscribe to paid features.`,`You must give us truthful information and keep your profile up to date. We may ask you to confirm your age and, where relevant, your guardian’s permission.`]},{id:`conta`,title:`Your account`,body:[`You sign in to Kayé with your Google account. We never see your Google password. You are responsible for everything that happens in your account and for protecting access to your email and your device.`,`The account is personal: do not share it or hand it over. If you think someone entered your account without permission, tell us straight away at {email}.`,`You can delete your account and your data whenever you want, in Settings. Deleting is final and we cannot recover what you deleted.`]},{id:`gratis-plus`,title:`Free, Kayé Plus and payments`,body:[`Exploring Kayé is free: discovering careers, areas, courses, institutions, companies, the market, news, deadlines, scholarships and internships, taking your first vocational test, following your streak and answering the challenge of the day. What is free for exploration today does not become paid without prior notice.`,`What is personalised is part of Kayé Plus, a paid subscription for people over 18: the Kursos with no daily limit and with a final exam, the Kursos certificate, reminders and subscriptions (deadline alerts by email and notifications), the personal plan (“My plan”), the CV as a PDF, unlimited psychotechnical and access-exam practice, unlimited simulations and interviews with feedback from the team. The CV as a PDF, the practice, the simulations and the interviews can be tried once, for free.`,`In the Kursos, a free account does one topic a day: the day counts when you finish the topic, and the others stay locked until the next day. A free account does not receive the Kursos certificate. The certificate is a recognition from Kayé: it is not an official diploma, it does not replace a recognised course and it does not guarantee a job, scholarship or place.`,`If you are under 18, you do one topic a day in the Kursos, without a certificate, and you do not see promotions for Kayé Plus. We never charge you anything.`,`Christmas gift: during the trial period, Kayé Plus is free for everyone and we charge nothing. We warn you in the app and/or by email at least 30 days before Plus becomes paid, and we only charge after you accept the conditions.`,`The expected price of Kayé Plus is 1,999 kwanzas a month and it may change before it opens. Before you pay, we show you, in kwanzas and with taxes included, the price, the period, the features included, the payment method and how to cancel.`,[`If the subscription renews automatically, we warn you before each renewal and you can cancel at any time in Settings; cancelling takes effect at the end of the period already paid.`,`We may change the price of Kayé Plus. The change only applies to later periods and we warn you at least 30 days ahead, so you can decide whether to continue.`,`Without prejudice to the rights consumer protection law gives you, we do not refund a period that has already started, unless the Service fails through our fault for a significant part of that period.`,`Payments are processed by authorised payment service providers. Kayé does not store your card or payment account details.`]]},{id:`independencia`,title:`Independence of the recommendations`,body:[`No institution or company pays to appear first. Nothing paid, including Kayé Plus, influences the recommendations, the order of what you see, the ranking of courses or your fit with a career.`,`The criteria for ranking courses are public and explained in the app itself. If there is ever sponsored content, it will always be identified as such and kept apart from the rest.`]},{id:`informacao`,title:`The information we show`,body:[`We gather information from public and official sources and name the source whenever possible. Even so, careers, salaries, tuition fees, deadlines and vacancies change, and we may be wrong or out of date.`,`Some numbers and texts are estimates or examples, and we say so when that is the case (“Estimated”, “Example”). Institutions marked “Example” are not real. Real institutions only show facts from public sources or that they confirmed to us.`,`The vocational test, the fit with each career, the recommendations and the challenges give hints about your interests and the market. They are not a diagnosis, a psychological assessment, an aptitude test or professional advice.`,`Before an important decision, such as paying for an enrolment, changing course or turning down an offer, check directly with the institution, the company or the official body. If you see a mistake, tell us at {email} and we will correct it.`]},{id:`sem-garantias`,title:`Guidance, not promises`,body:[`Kayé does not guarantee that you will find a job, be admitted to an institution, get a scholarship or an internship, earn a certain salary or that a career will be in demand in the future. The results depend on you and on many things we do not control.`,`The decisions you make about your studies, your work and your money are yours and your responsibility.`]},{id:`regras`,title:`Rules of use`,body:[`Use Kayé honestly, lawfully and with respect for others. It is not allowed to:`,[`knowingly give false information, for example in a testimonial, a salary, your profile or a request to a mentor;`,`pretend to be another person or an institution or company;`,`publish or ask for other people’s personal data without permission;`,`insult, threaten, harass or discriminate against anyone, or publish unlawful, offensive, violent or sexually explicit content;`,`try to enter parts of the Service you have no access to, bypass security measures, test for vulnerabilities without our written authorisation or disturb the Service’s operation;`,`copy, collect or reuse Kayé’s content, data or ranking automatically or in bulk (robots, data extraction, scraping), or resell them;`,`use the Service to send unsolicited messages or advertising;`,`use Kayé for purposes against the law, in particular the law protecting networks and information systems.`],`When testimonials and other contributions exist, they are reviewed before they appear. We may refuse, edit or remove what does not follow these rules, and report to the authorities what the law requires us to report.`]},{id:`o-teu-conteudo`,title:`Your content`,body:[`Your CV, your answers and everything you write in Kayé remain yours. We do not take ownership of any of it.`,`For the Service to work, you give Kayé a free, non-exclusive and limited licence to store, process and show that content only to you and to the people you choose (for example, when you publish your business card), and to handle it as the Privacy Policy explains. The licence ends when you delete the content or the account, except for backup copies that are deleted in the normal cycle.`,`If you publish your business card, you decide what appears and you can switch it off whenever you want. You are responsible for what you write and you guarantee you have the right to publish it.`,`If you send us suggestions, criticism or ideas, we may use them without paying you or crediting you, but without making your personal data public.`,`The model CVs belong to fictional people. You are free to use them as a starting point for yours.`]},{id:`propriedade`,title:`Kayé’s intellectual property`,body:[`The name, the logo, the design, the software, the database, the ranking, the texts and the rest of Kayé’s content belong to Kayé or to whoever licensed them to us, and are protected by Angolan copyright and industrial property law.`,`These terms give you no rights over this beyond what they say: we give you only the personal, limited, revocable and non-transferable right to use the Service for your personal guidance. You may not copy, modify, distribute, sell, rent or reverse engineer the Service, nor use the Kayé brand without our written permission.`,`The names and logos of institutions and companies belong to their owners and appear only to identify them. Photos belong to their authors and are used under their licences. If you hold a right and think something infringes it, write to {email} naming the content and the right, and we will look into it and, where appropriate, remove it.`]},{id:`terceiros`,title:`Institutions, companies and third-party links`,body:[`Kayé shows institutions, companies, scholarships, internships and news that are not ours. We are not a party to the relationship between you and them, we do not represent them or recommend them by that fact alone, and we are not responsible for what they do, promise or fail to do.`,`Links to third-party sites are a convenience. We do not control those sites or endorse them, and using them is at your own risk, under their terms.`,`When an institution or company publishes something in Kayé, it is responsible for what it publishes. We never give them your individual data.`]},{id:`funcionalidades`,title:`Interviews, mentors and other features involving people`,body:[`Interview practice with feedback: the answers you decide to send are read by the Kayé team to give you feedback and are handled as the Privacy Policy explains. The feedback is an opinion to help you practise, not an official assessment or a promise of results.`,`Mentors: mentors are independent people approved by us. They are not employees or agents of Kayé, and the conversations arranged with you are between you and them. Kayé does not guarantee the content of those conversations. Do not share sensitive data or make payments outside the Service’s rules.`,`CV as a PDF and business card: the document is created on your device from what you wrote. Check it before you send it: you are responsible for its content.`]},{id:`avisos`,title:`Communications and notices`,body:[`We send you messages from the Service when they are necessary (for example, confirming your email, reminders of deadlines you saved, changes to these terms or security notices).`,`We only send you news and promotions if you give us consent for that channel (email or notifications), which you can withdraw at any time in Settings or in the link in each email. We never send promotions to people under 18.`,`We respect the law on unsolicited electronic communications. We send WhatsApp messages only by hand and only to people who asked for them.`]},{id:`privacidade`,title:`Your personal data`,body:[`We handle your personal data in line with Law No. 22/11 of 17 June on the Protection of Personal Data, and as explained in our Privacy Policy, which is part of these terms. There we say what data we collect, why, for how long, who we share it with and how you exercise your rights.`]},{id:`disponibilidade`,title:`Availability of the service`,body:[`We do our best for Kayé to always be available, but we do not guarantee that it works without interruptions or errors. We may stop the Service, or part of it, for maintenance, updates, security reasons or problems outside our control (power or internet failures, supplier failures).`,`We may change, add or remove features. When a change affects you significantly, we give reasonable notice.`,`Kayé was designed for phones with a slow connection. If you have little internet, some parts may be slow or not open.`]},{id:`responsabilidade`,title:`Limits of our liability`,body:[`The Service is provided “as is” and “as available”. To the fullest extent the law allows, Kayé is not liable for: decisions you make based on the Service’s information; errors, delays or omissions in data published by institutions, companies and other sources; unavailability of the Service; loss of profits, opportunities, data or other indirect or consequential damage; or acts of third parties, including institutions, companies, mentors and other users.`,`If, despite this, we are liable to you, our total liability is limited, as far as the law allows, to the amount you paid Kayé in the 12 months before the event that gave rise to the claim (or, if the Service was free for you, to the minimum the law allows).`,`Nothing in these terms excludes or limits liability that the law does not allow to be excluded or limited, such as liability for wilful misconduct, gross negligence, damage to life, physical integrity or health, or the rights that consumer protection law guarantees you and that cannot be set aside by contract.`]},{id:`indemnizacao`,title:`Responsibility for your use`,body:[`You are responsible for how you use the Service and for what you publish in it. If you breach these terms or the law, and that causes harm to Kayé or to third parties (for example, by publishing unlawful content or content that infringes others’ rights), you may have to compensate us for the reasonable losses and costs that result, as far as the law allows.`]},{id:`suspensao`,title:`Suspending, ending and leaving`,body:[`You can stop using Kayé and delete your account whenever you want.`,`We may suspend or end access for anyone who breaches these terms or the law, endangers the security of the Service or of other people, or uses the Service fraudulently. Whenever possible we warn first and explain the reason, and you can answer us at {email}. In serious or urgent cases we may suspend immediately.`,`If a paid account is ended by our decision when you have not breached these terms, we refund the proportional amount for the period paid and not used.`,`What by its nature must continue after the contract ends (intellectual property, limits of liability, governing law and dispute resolution) continues.`]},{id:`forca-maior`,title:`Force majeure`,body:[`Neither party is liable for failures to perform caused by events beyond its reasonable control, such as natural disasters, war, acts of the authorities, general power or telecommunications failures, cyber attacks despite reasonable security measures, or failures of essential suppliers. The affected party tells the other and resumes performance as soon as possible.`]},{id:`alteracoes`,title:`Changes to these terms`,body:[`We may update these terms to reflect changes in the Service, the law or the way we work. The date of the version in force is at the top of this page.`,`If the change is important, we tell you in the app and/or by email at least 30 days ahead (or as soon as possible, if required by law or for security) and ask you to accept the new version. If you do not agree, you can delete your account before the change takes effect. Continuing to use the Service after that date means you accept the new version.`]},{id:`disposicoes`,title:`General provisions`,body:[`These terms, with the Privacy Policy and the specific notices, are the whole agreement between you and Kayé about the Service and replace earlier understandings.`,`If a part of these terms is invalid or cannot be enforced, the other parts remain in force and the invalid part is replaced by the one closest to its purpose. Not exercising a right does not mean giving it up.`,`You may not assign your rights and obligations to another person. Kayé may transfer the Service and this contract to another entity, for example in a reorganisation, telling you and without reducing your rights.`,`You agree to receive communications about the Service by electronic means (the app and the email you gave). Kayé can be read in Portuguese, English and French: in case of doubt or difference, the Portuguese text prevails.`]},{id:`lei-litigios`,title:`Governing law, complaints and disputes`,body:[`These terms are governed by the law of the Republic of Angola.`,`If you have a complaint, write to us first at {email}: we answer within a reasonable time and try to resolve it amicably. If you are a consumer, you may also turn to consumer protection bodies, such as the National Institute for Consumer Protection (INADEC), and, for personal data, the Data Protection Agency (APD).`,`For disputes that are not resolved amicably, the courts of the district of Luanda have jurisdiction, without prejudice to mandatory rules that allow you to go to the courts of your home and to the alternative dispute resolution means the law gives you. Nothing here obliges you to go to arbitration.`]},{id:`contacto`,title:`Contact`,body:[`Questions, requests or complaints about these terms: {email}.`]}]},fr:{intro:`Les règles pour utiliser Kayé : ce que tu peux attendre de nous, ce que nous attendons de toi et ce qui se passe quand quelque chose ne va pas.`,summary:[`Explorer Kayé est gratuit. Dans les Kursos, un compte gratuit fait un sujet par jour ; Kayé Plus (payant, pour les plus de 18 ans) enlève la limite et comprend le certificat et les rappels. Pendant l’essai de Noël, Plus est gratuit pour tous, et nous te prévenons avant qu’il devienne payant.`,`Kayé oriente, il ne décide pas à ta place et ne garantit ni emploi, ni bourse, ni place dans une formation. La décision est toujours la tienne.`,`Rien de payant n’influence les recommandations.`,`L’information vient de sources que nous indiquons, mais elle peut changer ou contenir des erreurs : vérifie auprès de l’établissement avant de payer ou de t’inscrire.`,`Ton CV et ce que tu écris sont à toi. Tu peux supprimer ton compte et tes données quand tu veux.`,`Entre 14 et 17 ans, tu peux utiliser Kayé avec l’accord de ton tuteur légal.`,`Ces conditions sont régies par le droit angolais. Tes droits de consommateur restent toujours protégés.`],sections:[{id:`quem-somos`,title:`Qui nous sommes et ce que sont ces conditions`,body:[`Kayé est une plateforme d’orientation professionnelle pour les jeunes en Angola, disponible sur kayeangola.com et dans les applications que Kayé publie (le « Service »). Dans ce texte, « Kayé », « nous » et « notre » désignent l’entité qui exploite le Service{operator}. « Tu » es la personne qui utilise le Service.`,`Ces conditions sont le contrat entre toi et Kayé. La Politique de confidentialité, qui explique comment nous traitons tes données, et les avis spécifiques affichés près d’une fonction (par exemple, les règles des entretiens ou de Kayé Plus) en font partie. En cas de différence, l’avis spécifique prévaut sur ces conditions pour cette fonction.`,`En créant un profil, en te connectant avec ton compte Google ou en continuant à utiliser le Service après les avoir lues, tu acceptes ces conditions. Si tu n’es pas d’accord, n’utilise pas le Service : tu peux continuer à explorer ce qui est ouvert sans créer de profil, mais sans rien enregistrer.`]},{id:`o-que-e`,title:`Ce qu’est Kayé`,body:[`Kayé aide les jeunes de 14 à 30 ans à découvrir des métiers, ce que chacun exige, ce qu’il rapporte et la demande qu’il a, où étudier et comment se préparer : tests d’orientation, comparaison de formations, d’établissements et d’entreprises, échéances de bourses et de candidatures, entraînement aux examens et aux entretiens, et un créateur de CV.`,`Kayé est un service d’orientation et d’information. Ce n’est pas un site d’emploi, il ne recrute pas, ce n’est pas un établissement d’enseignement, il n’accorde pas de bourses, il ne donne pas de conseil psychologique, juridique, médical ou financier, et il ne représente aucun établissement ni aucune entreprise.`]},{id:`quem-pode-usar`,title:`Qui peut l’utiliser`,body:[`Toute personne peut explorer ce qui est ouvert sans créer de profil. Pour créer un profil, tu dois avoir au moins 14 ans, donner des informations exactes et accepter ces conditions et la Politique de confidentialité.`,`Si tu as entre 14 et 17 ans, tu ne peux utiliser Kayé qu’avec la connaissance et l’autorisation de ton tuteur légal, que tu déclares en créant le profil. Il peut nous demander à tout moment de supprimer ton compte. Si tu es tuteur légal et que tu n’es pas d’accord pour qu’un mineur utilise Kayé, écris-nous et nous supprimerons le compte.`,`Par sécurité, les profils de mineurs ne sont jamais publics, ils ne voient pas les salaires, ne reçoivent aucun message promotionnel et ne peuvent pas souscrire aux fonctions payantes.`,`Tu dois nous donner des informations exactes et tenir ton profil à jour. Nous pouvons te demander de confirmer ton âge et, le cas échéant, l’autorisation de ton tuteur légal.`]},{id:`conta`,title:`Ton compte`,body:[`Tu te connectes à Kayé avec ton compte Google. Nous ne voyons jamais ton mot de passe Google. Tu es responsable de tout ce qui se passe dans ton compte et de la protection de l’accès à ton email et à ton appareil.`,`Le compte est personnel : ne le partage pas et ne le cède pas. Si tu penses que quelqu’un est entré dans ton compte sans autorisation, préviens-nous tout de suite à {email}.`,`Tu peux supprimer ton compte et tes données quand tu veux, dans Paramètres. La suppression est définitive et nous ne pouvons pas récupérer ce que tu as supprimé.`]},{id:`gratis-plus`,title:`Gratuit, Kayé Plus et paiements`,body:[`Explorer Kayé est gratuit : découvrir les carrières, les domaines, les formations, les établissements, les entreprises, le marché, l’actualité, les échéances, les bourses et les stages, faire ton premier test d’orientation, suivre ta série et répondre au défi du jour. Ce qui est gratuit aujourd’hui pour l’exploration ne devient pas payant sans préavis.`,`Ce qui est personnalisé fait partie de Kayé Plus, un abonnement payant pour les plus de 18 ans : les Kursos sans limite par jour et avec examen final, le certificat des Kursos, les rappels et les abonnements (alertes d’échéances par email et par notifications), le plan personnel (« Mon plan »), le CV en PDF, l’entraînement psychotechnique et aux examens d’accès sans limite, les simulations sans limite et les entretiens avec retour de l’équipe. Le CV en PDF, l’entraînement, les simulations et les entretiens peuvent être essayés une fois, gratuitement.`,`Dans les Kursos, un compte gratuit fait un sujet par jour : le jour compte quand tu termines le sujet, et les autres restent verrouillés jusqu’au lendemain. Un compte gratuit ne reçoit pas le certificat des Kursos. Le certificat est une reconnaissance de Kayé : ce n’est pas un diplôme officiel, il ne remplace pas une formation reconnue et ne garantit ni emploi, ni bourse, ni place.`,`Si tu as moins de 18 ans, tu fais un sujet par jour dans les Kursos, sans certificat, et tu ne vois pas de promotions de Kayé Plus. Nous ne te facturons jamais rien.`,`Cadeau de Noël : pendant la période d’essai, Kayé Plus est gratuit pour tous et nous ne facturons rien. Nous te prévenons dans l’app et/ou par email au moins 30 jours avant que Plus devienne payant, et nous ne facturons qu’après ton acceptation des conditions.`,`Le prix prévu de Kayé Plus est de 1 999 kwanzas par mois et il peut changer avant l’ouverture. Avant que tu paies, nous te montrons, en kwanzas et taxes comprises, le prix, la période, les fonctions incluses, le moyen de paiement et comment résilier.`,[`Si l’abonnement se renouvelle automatiquement, nous te prévenons avant chaque renouvellement et tu peux résilier à tout moment dans Paramètres ; la résiliation prend effet à la fin de la période déjà payée.`,`Nous pouvons modifier le prix de Kayé Plus. Le changement ne vaut que pour les périodes suivantes et nous te prévenons au moins 30 jours à l’avance, pour que tu décides de continuer ou non.`,`Sans préjudice des droits que la loi de protection du consommateur te donne, nous ne remboursons pas la période déjà commencée, sauf si le Service est défaillant par notre faute pendant une partie importante de cette période.`,`Les paiements sont traités par des prestataires de services de paiement agréés. Kayé ne conserve pas les données de ta carte ou de ton compte de paiement.`]]},{id:`independencia`,title:`Indépendance des recommandations`,body:[`Aucun établissement ni aucune entreprise ne paie pour apparaître en premier. Rien de payant, y compris Kayé Plus, n’influence les recommandations, l’ordre de ce que tu vois, le classement des formations ou ton adéquation à un métier.`,`Les critères du classement des formations sont publics et expliqués dans l’app elle-même. S’il y a un jour du contenu sponsorisé, il sera toujours identifié comme tel et séparé du reste.`]},{id:`informacao`,title:`L’information que nous montrons`,body:[`Nous réunissons l’information à partir de sources publiques et officielles et indiquons la source chaque fois que possible. Malgré cela, les métiers, les salaires, les frais de scolarité, les échéances et les offres changent, et nous pouvons nous tromper ou être dépassés.`,`Certains chiffres et textes sont des estimations ou des exemples, et nous le disons quand c’est le cas (« Estimé », « Exemple »). Les établissements marqués « Exemple » ne sont pas réels. Les établissements réels ne montrent que des faits de sources publiques ou qu’ils nous ont confirmés.`,`Le test d’orientation, l’adéquation à chaque métier, les recommandations et les défis donnent des pistes sur tes intérêts et le marché. Ce ne sont ni un diagnostic, ni une évaluation psychologique, ni un test d’aptitude, ni un avis professionnel.`,`Avant une décision importante, comme payer une inscription, changer de formation ou refuser une offre, vérifie directement auprès de l’établissement, de l’entreprise ou de l’organisme officiel. Si tu vois une erreur, dis-le-nous à {email} et nous la corrigerons.`]},{id:`sem-garantias`,title:`De l’orientation, pas des promesses`,body:[`Kayé ne garantit pas que tu trouveras un emploi, que tu seras admis dans un établissement, que tu obtiendras une bourse ou un stage, que tu gagneras un certain salaire ni qu’un métier sera demandé à l’avenir. Les résultats dépendent de toi et de beaucoup de choses que nous ne contrôlons pas.`,`Les décisions que tu prends sur tes études, ton travail et ton argent sont les tiennes et relèvent de ta responsabilité.`]},{id:`regras`,title:`Règles d’utilisation`,body:[`Utilise Kayé avec honnêteté, dans le respect de la loi et des autres. Il est interdit de :`,[`donner volontairement de fausses informations, par exemple dans un témoignage, un salaire, ton profil ou une demande à un mentor ;`,`te faire passer pour une autre personne ou pour un établissement ou une entreprise ;`,`publier ou demander les données personnelles d’autres personnes sans autorisation ;`,`insulter, menacer, harceler ou discriminer quiconque, ou publier du contenu illégal, offensant, violent ou sexuellement explicite ;`,`tenter d’accéder à des parties du Service auxquelles tu n’as pas accès, contourner les mesures de sécurité, tester des vulnérabilités sans notre autorisation écrite ou perturber le fonctionnement du Service ;`,`copier, collecter ou réutiliser le contenu, les données ou le classement de Kayé de façon automatique ou en masse (robots, extraction de données, scraping), ou les revendre ;`,`utiliser le Service pour envoyer des messages non sollicités ou de la publicité ;`,`utiliser Kayé à des fins contraires à la loi, notamment à la loi de protection des réseaux et systèmes informatiques.`],`Quand des témoignages et d’autres contributions existeront, ils seront relus avant d’apparaître. Nous pouvons refuser, modifier ou retirer ce qui ne respecte pas ces règles, et signaler aux autorités ce que la loi nous oblige à signaler.`]},{id:`o-teu-conteudo`,title:`Ton contenu`,body:[`Ton CV, tes réponses et tout ce que tu écris dans Kayé restent à toi. Nous ne prenons la propriété de rien de tout cela.`,`Pour que le Service fonctionne, tu donnes à Kayé une licence gratuite, non exclusive et limitée pour conserver, traiter et montrer ce contenu uniquement à toi et aux personnes que tu choisis (par exemple, quand tu publies ta carte de visite), et pour le traiter comme l’explique la Politique de confidentialité. La licence prend fin quand tu supprimes le contenu ou le compte, sauf les copies de sauvegarde qui sont supprimées dans le cycle normal.`,`Si tu publies ta carte de visite, tu décides de ce qui apparaît et tu peux la désactiver quand tu veux. Tu es responsable de ce que tu écris et tu garantis avoir le droit de le publier.`,`Si tu nous envoies des suggestions, des critiques ou des idées, nous pouvons les utiliser sans te payer ni te citer, mais sans rendre publiques tes données personnelles.`,`Les CV modèles appartiennent à des personnes fictives. Tu peux les utiliser librement comme point de départ pour le tien.`]},{id:`propriedade`,title:`Propriété intellectuelle de Kayé`,body:[`Le nom, le logo, le design, le logiciel, la base de données, le classement, les textes et le reste du contenu de Kayé appartiennent à Kayé ou à qui nous en a concédé la licence, et sont protégés par la loi angolaise sur le droit d’auteur et la propriété industrielle.`,`Ces conditions ne te donnent aucun droit sur cela au-delà de ce qu’elles disent : nous te donnons seulement le droit personnel, limité, révocable et non transmissible d’utiliser le Service pour ton orientation personnelle. Tu ne peux pas copier, modifier, distribuer, vendre, louer ni décompiler le Service, ni utiliser la marque Kayé sans notre autorisation écrite.`,`Les noms et logos des établissements et des entreprises appartiennent à leurs propriétaires et n’apparaissent que pour les identifier. Les photos appartiennent à leurs auteurs et sont utilisées selon leurs licences. Si tu es titulaire d’un droit et penses que quelque chose le viole, écris à {email} en indiquant le contenu et le droit, et nous examinerons et, le cas échéant, retirerons.`]},{id:`terceiros`,title:`Établissements, entreprises et liens de tiers`,body:[`Kayé montre des établissements, des entreprises, des bourses, des stages et des actualités qui ne sont pas à nous. Nous ne sommes pas partie à la relation entre toi et eux, nous ne les représentons pas ni ne les recommandons du seul fait de leur présence, et nous ne répondons pas de ce qu’ils font, promettent ou omettent de faire.`,`Les liens vers des sites de tiers sont une commodité. Nous ne contrôlons pas ces sites et ne les cautionnons pas, et leur utilisation est à tes risques, selon leurs conditions.`,`Quand un établissement ou une entreprise publie quelque chose dans Kayé, c’est lui le responsable de ce qu’il publie. Nous ne leur donnons jamais tes données individuelles.`]},{id:`funcionalidades`,title:`Entretiens, mentors et autres fonctions impliquant des personnes`,body:[`Entraînement aux entretiens avec retour : les réponses que tu décides d’envoyer sont lues par l’équipe de Kayé pour te donner un retour et sont traitées comme l’explique la Politique de confidentialité. Le retour est un avis pour t’aider à t’entraîner, pas une évaluation officielle ni une promesse de résultat.`,`Mentors : les mentors sont des personnes indépendantes approuvées par nous. Ils ne sont ni salariés ni agents de Kayé, et les conversations convenues avec toi se tiennent entre toi et eux. Kayé ne garantit pas le contenu de ces conversations. Ne partage pas de données sensibles et ne fais pas de paiements en dehors des règles du Service.`,`CV en PDF et carte de visite : le document est créé sur ton appareil à partir de ce que tu as écrit. Vérifie-le avant de l’envoyer : tu es responsable de son contenu.`]},{id:`avisos`,title:`Communications et avis`,body:[`Nous t’envoyons des messages du Service quand ils sont nécessaires (par exemple, la confirmation de ton email, des rappels d’échéances que tu as enregistrées, des changements de ces conditions ou des avis de sécurité).`,`Nous ne t’envoyons des actualités et des promotions que si tu nous donnes ton consentement pour ce canal (email ou notifications), que tu peux retirer à tout moment dans Paramètres ou dans le lien de chaque email. Nous n’envoyons jamais de promotions aux moins de 18 ans.`,`Nous respectons la loi sur les communications électroniques non sollicitées. Nous n’envoyons des messages WhatsApp qu’à la main et seulement à qui l’a demandé.`]},{id:`privacidade`,title:`Tes données personnelles`,body:[`Nous traitons tes données personnelles conformément à la Loi n° 22/11 du 17 juin sur la Protection des Données Personnelles, et comme l’explique notre Politique de confidentialité, qui fait partie de ces conditions. Nous y disons quelles données nous collectons, pourquoi, pendant combien de temps, avec qui nous les partageons et comment tu exerces tes droits.`]},{id:`disponibilidade`,title:`Disponibilité du service`,body:[`Nous faisons de notre mieux pour que Kayé soit toujours disponible, mais nous ne garantissons pas qu’il fonctionne sans interruption ni erreur. Nous pouvons arrêter le Service, ou une partie, pour maintenance, mises à jour, raisons de sécurité ou problèmes hors de notre contrôle (pannes d’électricité ou d’internet, défaillances de fournisseurs).`,`Nous pouvons modifier, ajouter ou retirer des fonctions. Quand un changement te touche de façon importante, nous te prévenons avec un préavis raisonnable.`,`Kayé a été pensé pour les téléphones à connexion lente. Si tu as peu d’internet, certaines parties peuvent être lentes ou ne pas s’ouvrir.`]},{id:`responsabilidade`,title:`Limites de notre responsabilité`,body:[`Le Service est fourni « en l’état » et « selon disponibilité ». Dans la mesure maximale permise par la loi, Kayé n’est pas responsable : des décisions que tu prends sur la base des informations du Service ; des erreurs, retards ou omissions dans les données publiées par les établissements, les entreprises et d’autres sources ; de l’indisponibilité du Service ; de la perte de bénéfices, d’opportunités, de données ou d’autres dommages indirects ou consécutifs ; ni des actes de tiers, y compris les établissements, les entreprises, les mentors et les autres utilisateurs.`,`Si, malgré cela, nous sommes responsables envers toi, notre responsabilité totale est limitée, dans la mesure permise par la loi, au montant que tu as payé à Kayé au cours des 12 mois précédant le fait à l’origine de la réclamation (ou, si le Service était gratuit pour toi, au minimum permis par la loi).`,`Rien dans ces conditions n’exclut ni ne limite la responsabilité que la loi ne permet pas d’exclure ou de limiter, comme la responsabilité pour dol, faute grave, atteinte à la vie, à l’intégrité physique ou à la santé, ni les droits que la loi de protection du consommateur te garantit et qui ne peuvent être écartés par contrat.`]},{id:`indemnizacao`,title:`Responsabilité de ton utilisation`,body:[`Tu es responsable de l’usage que tu fais du Service et de ce que tu y publies. Si tu violes ces conditions ou la loi, et que cela cause un préjudice à Kayé ou à des tiers (par exemple, en publiant un contenu illicite ou qui viole les droits d’autrui), tu peux devoir nous indemniser des pertes et frais raisonnables qui en résultent, dans la mesure permise par la loi.`]},{id:`suspensao`,title:`Suspendre, mettre fin et partir`,body:[`Tu peux cesser d’utiliser Kayé et supprimer ton compte quand tu veux.`,`Nous pouvons suspendre ou mettre fin à l’accès de qui viole ces conditions ou la loi, met en danger la sécurité du Service ou d’autres personnes, ou utilise le Service de façon frauduleuse. Chaque fois que possible, nous prévenons d’abord et expliquons le motif, et tu peux nous répondre à {email}. Dans les cas graves ou urgents, nous pouvons suspendre immédiatement.`,`Si un compte payant est clôturé par notre décision alors que tu n’as pas violé ces conditions, nous remboursons le montant proportionnel à la période payée et non utilisée.`,`Ce qui, par sa nature, doit continuer après la fin du contrat (propriété intellectuelle, limites de responsabilité, droit applicable et règlement des litiges) continue.`]},{id:`forca-maior`,title:`Force majeure`,body:[`Aucune des parties n’est responsable des manquements causés par des événements hors de son contrôle raisonnable, comme les catastrophes naturelles, la guerre, les actes des autorités, les pannes générales d’électricité ou de télécommunications, les attaques informatiques malgré des mesures de sécurité raisonnables, ou les défaillances de fournisseurs essentiels. La partie touchée prévient l’autre et reprend l’exécution dès que possible.`]},{id:`alteracoes`,title:`Modifications de ces conditions`,body:[`Nous pouvons mettre à jour ces conditions pour refléter des changements du Service, de la loi ou de notre manière de travailler. La date de la version en vigueur est en haut de cette page.`,`Si le changement est important, nous te prévenons dans l’app et/ou par email au moins 30 jours à l’avance (ou dès que possible, si la loi ou la sécurité l’exige) et te demandons d’accepter la nouvelle version. Si tu n’es pas d’accord, tu peux supprimer ton compte avant l’entrée en vigueur du changement. Continuer à utiliser le Service après cette date signifie que tu acceptes la nouvelle version.`]},{id:`disposicoes`,title:`Dispositions générales`,body:[`Ces conditions, avec la Politique de confidentialité et les avis spécifiques, constituent l’accord complet entre toi et Kayé sur le Service et remplacent les accords antérieurs.`,`Si une partie de ces conditions est invalide ou inapplicable, les autres parties restent en vigueur et la partie invalide est remplacée par celle qui se rapproche le plus de son objectif. Ne pas exercer un droit ne signifie pas y renoncer.`,`Tu ne peux pas céder tes droits et obligations à une autre personne. Kayé peut transférer le Service et ce contrat à une autre entité, par exemple lors d’une réorganisation, en te prévenant et sans réduire tes droits.`,`Tu acceptes de recevoir les communications sur le Service par voie électronique (l’app et l’email que tu as donné). Kayé peut être lu en portugais, en anglais et en français : en cas de doute ou de différence, le texte en portugais prévaut.`]},{id:`lei-litigios`,title:`Droit applicable, réclamations et litiges`,body:[`Ces conditions sont régies par le droit de la République d’Angola.`,`Si tu as une réclamation, écris-nous d’abord à {email} : nous répondons dans un délai raisonnable et essayons de la résoudre à l’amiable. Si tu es consommateur, tu peux aussi t’adresser aux organismes de protection des consommateurs, comme l’Institut National de Défense du Consommateur (INADEC), et, pour les données personnelles, à l’Agence de Protection des Données (APD).`,`Pour les litiges non résolus à l’amiable, les tribunaux de la comarca de Luanda sont compétents, sans préjudice des règles impératives qui te permettent de saisir les tribunaux de ton domicile et des modes alternatifs de règlement des litiges que la loi te donne. Rien ici ne t’oblige à recourir à l’arbitrage.`]},{id:`contacto`,title:`Contact`,body:[`Questions, demandes ou réclamations sur ces conditions : {email}.`]}]}},r=t();function i(){return(0,r.jsx)(e,{kind:`terms`,doc:n})}export{i as default};